use vstd::prelude::*;

verus! {

    // Given a, b in [-100,100] with same parity (so a+b and a−b are even),
    // find x,y : i8 so that x+y = a and x−y = b.
    fn solve(a: i8, b: i8) -> (result: (i8, i8))
        requires
            -100 <= a && a <= 100,
            -100 <= b && b <= 100,
            // same parity ⇒ both sum and difference are even
            ((a + b) % 2 == 0),
            ((a - b) % 2 == 0),
        ensures
            // post‐condition: the returned pair satisfies the equations
            let x = result.0;
            let y = result.1;
            x + y == a &&
            x - y == b,
    {
        // Lift to i16 to avoid overflow when adding/subtracting
        let sum_i16: i16  = a as i16 + b as i16;
        let diff_i16: i16 = a as i16 - b as i16;

        // By hypothesis, these are even
        assert(sum_i16  % 2 == 0);
        assert(diff_i16 % 2 == 0);

        // Compute the half‐values
        let x_i16: i16 = sum_i16  / 2;
        let y_i16: i16 = diff_i16 / 2;

        // Because a,b ∈ [−100,100], we get x_i16,y_i16 ∈ [−100,100]
        assert(-100 <= x_i16 && x_i16 <= 100);
        assert(-100 <= y_i16 && y_i16 <= 100);

        // Safe to cast back to i8
        let x: i8 = x_i16 as i8;
        let y: i8 = y_i16 as i8;

        // Prove correctness in i16, then conclude for i8
        assert(x_i16 + y_i16 == a as i16);
        assert(x_i16 - y_i16 == b as i16);

        // Return the solution
        (x, y)
    }

}

